insert into public.quizzes (id, title, instructions, time_limit_minutes, max_attempts, published, show_results, category, feedback_mode, created_by) values ('3c4acb47-c7bb-57f9-b94f-524e02dd4bb0', 'A1.1 Water · Topic quiz (HL)', 'Topic quiz for A1.1 Water, DP1 Term 1 (HL). Questions come from the interactive lessons. Written answers are marked against the mark scheme; your teacher checks every mark.', null, 2, false, true, 'quiz', 'hybrid', 'a9774d11-5d83-4bae-8da1-a6fb81c7dd7e') on conflict (id) do update set title = excluded.title, instructions = excluded.instructions;
insert into public.questions (id, kind, prompt, options, marks) values ('ae261e7e-69b4-58b3-b761-064a2a90458d', 'short', '1. State where the first cells originated, and suggest one reason why life began there rather than on dry land.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('ae261e7e-69b4-58b3-b761-064a2a90458d', 'The first cells originated in oceans or other bodies of water. Reason: reactions can happen in solution / water absorbs harmful UV radiation / large bodies of water have stable temperatures / dissolved substances are brought together.', 'The first cells originated in oceans or other bodies of water. Reason: reactions can happen in solution / water absorbs harmful UV radiation / large bodies of water have stable temperatures / dissolved substances are brought together.', '[{"text": "Marking point 1", "any": ["ocean", "sea", "water"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["solution", "dissolv", "ultraviolet", " uv ", "radiation", "stable temperature", "temperature changes slowly", "temperature change slowly", "stable", "concentrat", "brought together"], "all": [], "marks": 1}]'::jsonb, 'The first cells originated in oceans or other bodies of water. Reason: reactions can happen in solution / water absorbs harmful UV radiation / large bodies of water have stable temperatures / dissolved substances are brought together.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('3c4acb47-c7bb-57f9-b94f-524e02dd4bb0', 'ae261e7e-69b4-58b3-b761-064a2a90458d', 1);
insert into public.questions (id, kind, prompt, options, marks) values ('c6cbda12-8779-566a-ad88-bc9e997626fb', 'short', '2. List four reasons why life depends on water. Beside each one write a single sentence saying why it matters to a cell or an organism.', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c6cbda12-8779-566a-ad88-bc9e997626fb', 'Any four, each linked to a consequence: good solvent → reactions and transport happen in solution; liquid over a wide temperature range → organisms can live across those temperatures; high specific heat capacity → stable cell and habitat temperatures; high cohesion → water columns in xylem, surface tension; reactant → used in photosynthesis and hydrolysis; transparent → aquatic producers can photosynthesise; ice less dense than water → ice floats and insulates the water below.', 'Any four, each linked to a consequence: good solvent → reactions and transport happen in solution; liquid over a wide temperature range → organisms can live across those temperatures; high specific heat capacity → stable cell and habitat temperatures; high cohesion → water columns in xylem, surface tension; reactant → used in photosynthesis and hydrolysis; transparent → aquatic producers can photosynthesise; ice less dense than water → ice floats and insulates the water below.', '[{"text": "Marking point 1", "any": ["solvent", "dissolv"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["liquid over", "liquid at", "range of temperature", "temperatures at which", "stays liquid", "is liquid"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["specific heat", "energy to heat", "heat capacity", "temperature stable", "stable temperature", "resists", "slowly"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["reactant", "photosynthesis", "hydrolysis"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["ice floats", "ice is less dense", "less dense", "insulat", "floats"], "all": [], "marks": 1}, {"text": "Marking point 6", "any": ["cohesion", "xylem", "transparent", "light"], "all": [], "marks": 1}]'::jsonb, 'Any four, each linked to a consequence: good solvent → reactions and transport happen in solution; liquid over a wide temperature range → organisms can live across those temperatures; high specific heat capacity → stable cell and habitat temperatures; high cohesion → water columns in xylem, surface tension; reactant → used in photosynthesis and hydrolysis; transparent → aquatic producers can photosynthesise; ice less dense than water → ice floats and insulates the water below.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('3c4acb47-c7bb-57f9-b94f-524e02dd4bb0', 'c6cbda12-8779-566a-ad88-bc9e997626fb', 2);
insert into public.questions (id, kind, prompt, options, marks) values ('0c2877a5-ceda-57e8-bccf-16a381d46953', 'short', '4(a). Outline how an ionic bond forms between a sodium atom and a chlorine atom.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('0c2877a5-ceda-57e8-bccf-16a381d46953', 'Sodium transfers its one outer electron to chlorine, so both have full outer shells; sodium becomes a positive ion (Na⁺, cation) and chlorine a negative ion (Cl⁻, anion); the attraction between the opposite charges is the ionic bond.', 'Sodium transfers its one outer electron to chlorine, so both have full outer shells; sodium becomes a positive ion (Na⁺, cation) and chlorine a negative ion (Cl⁻, anion); the attraction between the opposite charges is the ionic bond.', '[{"text": "Marking point 1", "any": ["transfer", "gives", "gains", "loses", "donat", "lost", "gained"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["opposite charge", "attract", "cation", "anion", "positive ion", "negative ion"], "all": [], "marks": 1}]'::jsonb, 'Sodium transfers its one outer electron to chlorine, so both have full outer shells; sodium becomes a positive ion (Na⁺, cation) and chlorine a negative ion (Cl⁻, anion); the attraction between the opposite charges is the ionic bond.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('3c4acb47-c7bb-57f9-b94f-524e02dd4bb0', '0c2877a5-ceda-57e8-bccf-16a381d46953', 3);
insert into public.questions (id, kind, prompt, options, marks) values ('93f51e69-7f7d-5905-a89b-4aa664a3a275', 'short', '4(b). Outline how a covalent bond forms between an oxygen atom and a hydrogen atom.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('93f51e69-7f7d-5905-a89b-4aa664a3a275', 'Oxygen and hydrogen each contribute one electron to a shared pair; the shared pair is attracted to both nuclei, holding the atoms together (oxygen forms two such bonds because it needs two more electrons).', 'Oxygen and hydrogen each contribute one electron to a shared pair; the shared pair is attracted to both nuclei, holding the atoms together (oxygen forms two such bonds because it needs two more electrons).', '[{"text": "Marking point 1", "any": ["shar"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["both nuclei", "pair", "each contribute", "one electron each", "attracted to both", "full outer shell", "two covalent", "two bonds", "needs two"], "all": [], "marks": 1}]'::jsonb, 'Oxygen and hydrogen each contribute one electron to a shared pair; the shared pair is attracted to both nuclei, holding the atoms together (oxygen forms two such bonds because it needs two more electrons).') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('3c4acb47-c7bb-57f9-b94f-524e02dd4bb0', '93f51e69-7f7d-5905-a89b-4aa664a3a275', 4);
