insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('cc711fe9-a12f-5a1a-9486-2d53e537b292', 'In the two O–H bonds, between the oxygen atom and each hydrogen atom.', 'In the two O–H bonds, between the oxygen atom and each hydrogen atom.', '[{"text": "Marking point 1", "any": ["o h", "oxygen and hydrogen", "oxygen and each hydrogen", "oxygen and the hydrogen", "between the oxygen", "hydrogen and oxygen"], "all": [], "marks": 1}]'::jsonb, 'In the two O–H bonds, between the oxygen atom and each hydrogen atom.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('3c4acb47-c7bb-57f9-b94f-524e02dd4bb0', 'cc711fe9-a12f-5a1a-9486-2d53e537b292', 5);
insert into public.questions (id, kind, prompt, options, marks) values ('627637a8-96a8-510c-a6bc-b0235999f9bf', 'short', '5(b). Explain why the electrons in an O–H bond are not shared equally, and why this gives the oxygen a partial negative charge and each hydrogen a partial positive charge.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('627637a8-96a8-510c-a6bc-b0235999f9bf', 'Oxygen is more electronegative and attracts the shared electrons more strongly, so they spend more time nearer the oxygen; oxygen becomes partially negative (δ−) and each hydrogen partially positive (δ+); because the molecule is bent, the charges do not cancel, so water is polar.', 'Oxygen is more electronegative and attracts the shared electrons more strongly, so they spend more time nearer the oxygen; oxygen becomes partially negative (δ−) and each hydrogen partially positive (δ+); because the molecule is bent, the charges do not cancel, so water is polar.', '[{"text": "Marking point 1", "any": ["electronegativ", "attracts the shared electrons more", "attracts electrons more", "more strongly", "stronger pull", "pulls the electrons", "attracts the electrons"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["closer to the oxygen", "nearer the oxygen", "near the oxygen", "nearer to oxygen", "closer to oxygen"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["bent", "do not cancel", "don t cancel"], "all": [], "marks": 1}]'::jsonb, 'Oxygen is more electronegative and attracts the shared electrons more strongly, so they spend more time nearer the oxygen; oxygen becomes partially negative (δ−) and each hydrogen partially positive (δ+); because the molecule is bent, the charges do not cancel, so water is polar.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('3c4acb47-c7bb-57f9-b94f-524e02dd4bb0', '627637a8-96a8-510c-a6bc-b0235999f9bf', 6);
