insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e7eab325-ae23-5b12-9017-57e2274508f3', 'A molecule inside the liquid is attracted equally in all directions; a molecule at the surface has no water above it, so it is pulled sideways and downwards; surface molecules are drawn together into a layer that resists being broken.', 'A molecule inside the liquid is attracted equally in all directions; a molecule at the surface has no water above it, so it is pulled sideways and downwards; surface molecules are drawn together into a layer that resists being broken.', '[{"text": "Marking point 1", "any": ["no water above", "nothing above", "at the surface", "surface molecules", "top layer"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sideways", "downward", "inward", "pulled together", "all directions", "hydrogen bond", "cohesion"], "all": [], "marks": 1}]'::jsonb, 'A molecule inside the liquid is attracted equally in all directions; a molecule at the surface has no water above it, so it is pulled sideways and downwards; surface molecules are drawn together into a layer that resists being broken.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
