insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('6e56d547-29a3-5160-bd6a-0e7c2035cefc', 'The δ+ hydrogen of one water molecule is attracted to the δ− oxygen of a neighbouring water molecule; this electrostatic attraction between molecules is a hydrogen bond.', 'The δ+ hydrogen of one water molecule is attracted to the δ− oxygen of a neighbouring water molecule; this electrostatic attraction between molecules is a hydrogen bond.', '[{"text": "Marking point 1", "any": ["partial positive", "slightly positive", "positive hydrogen"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["partial negative", "slightly negative", "negative oxygen", "neighbouring", "another water", "other molecule", "another molecule"], "all": [], "marks": 1}]'::jsonb, 'The δ+ hydrogen of one water molecule is attracted to the δ− oxygen of a neighbouring water molecule; this electrostatic attraction between molecules is a hydrogen bond.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
