insert into public.questions (id, kind, prompt, options, marks) values ('a926408d-f018-59c1-a212-258f0c0ac5be', 'short', '6(b). A single hydrogen bond is weak. Outline two consequences of the collective strength of the many hydrogen bonds in liquid water.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('a926408d-f018-59c1-a212-258f0c0ac5be', 'Any two: water is liquid at temperatures suitable for life; high specific heat capacity; high latent heat of vaporisation; strong cohesion holds water columns in xylem; high surface tension; ice is less dense and floats.', 'Any two: water is liquid at temperatures suitable for life; high specific heat capacity; high latent heat of vaporisation; strong cohesion holds water columns in xylem; high surface tension; ice is less dense and floats.', '[{"text": "Marking point 1", "any": ["liquid", "specific heat", "heat capacity", "energy to heat", "latent heat", "evaporat"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["cohesion", "surface tension", "xylem", "column", "ice", "tension"], "all": [], "marks": 1}]'::jsonb, 'Any two: water is liquid at temperatures suitable for life; high specific heat capacity; high latent heat of vaporisation; strong cohesion holds water columns in xylem; high surface tension; ice is less dense and floats.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
