insert into public.questions (id, kind, prompt, options, marks) values ('e20b6797-f690-5848-8847-cbb6803c59b7', 'short', '8. Describe how water moves through the xylem of a vascular plant, from the root to the leaf.', '[]'::jsonb, 4) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e20b6797-f690-5848-8847-cbb6803c59b7', 'Water is absorbed from the soil by root hair cells and passes into the xylem; it evaporates from mesophyll cells and leaves through the stomata (transpiration); this creates tension at the top of the column; cohesion holds the molecules together so the continuous column is pulled up without breaking; adhesion to the xylem walls helps.', 'Water is absorbed from the soil by root hair cells and passes into the xylem; it evaporates from mesophyll cells and leaves through the stomata (transpiration); this creates tension at the top of the column; cohesion holds the molecules together so the continuous column is pulled up without breaking; adhesion to the xylem walls helps.', '[{"text": "Marking point 1", "any": ["root", "soil"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["transpiration", "evaporat", "stomata"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["tension", "pull", "suction"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["cohesion", "continuous", "column", "hydrogen bond"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["adhesion", "xylem wall", "walls"], "all": [], "marks": 1}]'::jsonb, 'Water is absorbed from the soil by root hair cells and passes into the xylem; it evaporates from mesophyll cells and leaves through the stomata (transpiration); this creates tension at the top of the column; cohesion holds the molecules together so the continuous column is pulled up without breaking; adhesion to the xylem walls helps.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('167f5acb-5413-5607-bf6e-df05a51080af', 'e20b6797-f690-5848-8847-cbb6803c59b7', 13);
insert into public.questions (id, kind, prompt, options, marks) values ('e7eab325-ae23-5b12-9017-57e2274508f3', 'short', '9(a). Outline the cause of surface tension.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e7eab325-ae23-5b12-9017-57e2274508f3', 'A molecule inside the liquid is attracted equally in all directions; a molecule at the surface has no water above it, so it is pulled sideways and downwards; surface molecules are drawn together into a layer that resists being broken.', 'A molecule inside the liquid is attracted equally in all directions; a molecule at the surface has no water above it, so it is pulled sideways and downwards; surface molecules are drawn together into a layer that resists being broken.', '[{"text": "Marking point 1", "any": ["no water above", "nothing above", "at the surface", "surface molecules", "top layer"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["sideways", "downward", "inward", "pulled together", "all directions", "hydrogen bond", "cohesion"], "all": [], "marks": 1}]'::jsonb, 'A molecule inside the liquid is attracted equally in all directions; a molecule at the surface has no water above it, so it is pulled sideways and downwards; surface molecules are drawn together into a layer that resists being broken.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
