insert into public.questions (id, kind, prompt, options, marks) values ('db32fbd9-8655-5285-942f-541d94742468', 'short', '1. Which of these contain carbon: a cotton T-shirt, petrol, a strand of hair, table sugar, diamond, water? Name the one that contains carbon but is NOT called organic, and say what that tells you.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('db32fbd9-8655-5285-942f-541d94742468', 'All except water contain carbon (cellulose, hydrocarbons, keratin, sucrose, carbon). Diamond contains carbon but is not organic, so containing carbon does not always make a substance organic.', 'All except water contain carbon (cellulose, hydrocarbons, keratin, sucrose, carbon). Diamond contains carbon but is not organic, so containing carbon does not always make a substance organic.', '[{"text": "Marking point 1", "any": ["diamond"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["not always", "does not mean", "doesn t mean", "not all", "not necessarily", "not every", "does not always", "doesn t always", "living", "organism"], "all": [], "marks": 1}]'::jsonb, 'All except water contain carbon (cellulose, hydrocarbons, keratin, sucrose, carbon). Diamond contains carbon but is not organic, so containing carbon does not always make a substance organic.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('b01926e3-c92d-5fbd-bb9c-c7ed0ad72433', 'db32fbd9-8655-5285-942f-541d94742468', 1);
