insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d28e1cb5-0044-53d3-8c5c-b5d03a5d2890', 'An organic compound contains carbon and is produced by, or characteristic of, living organisms. Not organic: carbon dioxide, carbonates, hydrogencarbonates, carbides, cyanides, diamond or graphite.', 'An organic compound contains carbon and is produced by, or characteristic of, living organisms. Not organic: carbon dioxide, carbonates, hydrogencarbonates, carbides, cyanides, diamond or graphite.', '[{"text": "Marking point 1", "any": ["produced by", "characteristic of"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["carbon dioxide", "co2", "carbonate", "carbide", "cyanide", "diamond", "graphite"], "all": [], "marks": 1}]'::jsonb, 'An organic compound contains carbon and is produced by, or characteristic of, living organisms. Not organic: carbon dioxide, carbonates, hydrogencarbonates, carbides, cyanides, diamond or graphite.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
