insert into public.questions (id, kind, prompt, options, marks) values ('e897f49b-0f30-55f3-af95-1d4df2219080', 'short', '11(a). Discuss the benefit of polysaccharide coiling and branching during polymerisation.', '[]'::jsonb, 3) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('e897f49b-0f30-55f3-af95-1d4df2219080', 'Compact: coiling and branching store many glucose units in a small volume. Little effect on water potential: insoluble, unlike free glucose which would draw water in by osmosis. Too large to leave the cell. Branching gives many ends for enzymes to work on at once, so glucose is released quickly. Cost: extra enzymes are needed to make the 1,6 branch points.', 'Compact: coiling and branching store many glucose units in a small volume. Little effect on water potential: insoluble, unlike free glucose which would draw water in by osmosis. Too large to leave the cell. Branching gives many ends for enzymes to work on at once, so glucose is released quickly. Cost: extra enzymes are needed to make the 1,6 branch points.', '[{"text": "Marking point 1", "any": ["compact", "small volume", "space", "coil"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["water potential", "osmo", "insoluble", "less soluble"], "all": [], "marks": 1}, {"text": "Marking point 3", "any": ["cannot leave", "can t leave", "stays in", "large", "membrane"], "all": [], "marks": 1}, {"text": "Marking point 4", "any": ["many ends", "ends", "quick", "rapid", "fast"], "all": [], "marks": 1}, {"text": "Marking point 5", "any": ["cost", "disadvantage", "extra enzyme", "energy to make"], "all": [], "marks": 1}]'::jsonb, 'Compact: coiling and branching store many glucose units in a small volume. Little effect on water potential: insoluble, unlike free glucose which would draw water in by osmosis. Too large to leave the cell. Branching gives many ends for enzymes to work on at once, so glucose is released quickly. Cost: extra enzymes are needed to make the 1,6 branch points.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('b01926e3-c92d-5fbd-bb9c-c7ed0ad72433', 'e897f49b-0f30-55f3-af95-1d4df2219080', 25);
insert into public.questions (id, kind, prompt, options, marks) values ('c8f922fb-30ef-5833-b3c9-e3930d63fc16', 'short', '11(b). Explain how condensation and hydrolysis of alpha-glucose monomers build up and mobilise an energy store.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c8f922fb-30ef-5833-b3c9-e3930d63fc16', 'When glucose is plentiful (after a meal), condensation joins alpha-glucose by glycosidic bonds, releasing water, building the store. When glucose is needed (between meals, exercise), hydrolysis adds water to break the bonds and release glucose.', 'When glucose is plentiful (after a meal), condensation joins alpha-glucose by glycosidic bonds, releasing water, building the store. When glucose is needed (between meals, exercise), hydrolysis adds water to break the bonds and release glucose.', '[{"text": "Marking point 1", "any": ["condensation"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["hydrolysis"], "all": [], "marks": 1}]'::jsonb, 'When glucose is plentiful (after a meal), condensation joins alpha-glucose by glycosidic bonds, releasing water, building the store. When glucose is needed (between meals, exercise), hydrolysis adds water to break the bonds and release glucose.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
insert into public.quiz_questions (quiz_id, question_id, position) values ('b01926e3-c92d-5fbd-bb9c-c7ed0ad72433', 'c8f922fb-30ef-5833-b3c9-e3930d63fc16', 26);
