insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('b65628b9-df0c-59b6-b5ee-3aaa3586977e', 'Both C₆H₁₂O₆; the –OH on carbon 1 points down in alpha-glucose and up in beta-glucose. Alpha-glucose forms starch and glycogen; beta-glucose forms cellulose.', 'Both C₆H₁₂O₆; the –OH on carbon 1 points down in alpha-glucose and up in beta-glucose. Alpha-glucose forms starch and glycogen; beta-glucose forms cellulose.', '[{"text": "Marking point 1", "any": ["carbon 1", "c1", " oh ", "hydroxyl"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": [], "all": ["alpha", "starch"], "marks": 1}]'::jsonb, 'Both C₆H₁₂O₆; the –OH on carbon 1 points down in alpha-glucose and up in beta-glucose. Alpha-glucose forms starch and glycogen; beta-glucose forms cellulose.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
