insert into public.questions (id, kind, prompt, options, marks) values ('387dbaa7-4d40-5acb-8c13-9b846eb0f73b', 'short', '3(b). Outline the cause and the consequence of covalent bonds between atoms.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('387dbaa7-4d40-5acb-8c13-9b846eb0f73b', 'Cause: atoms share pairs of electrons so each gets a full outer shell. Consequence: the atoms are held strongly together in fixed directions, so molecules have a definite 3D shape and are stable (enzymes are needed to break them).', 'Cause: atoms share pairs of electrons so each gets a full outer shell. Consequence: the atoms are held strongly together in fixed directions, so molecules have a definite 3D shape and are stable (enzymes are needed to break them).', '[{"text": "Marking point 1", "any": ["shar"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["strong", "fixed", "shape", "stable", "direction", "enzyme"], "all": [], "marks": 1}]'::jsonb, 'Cause: atoms share pairs of electrons so each gets a full outer shell. Consequence: the atoms are held strongly together in fixed directions, so molecules have a definite 3D shape and are stable (enzymes are needed to break them).') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
