insert into public.questions (id, kind, prompt, options, marks) values ('f0489779-e5cf-5557-a839-9effac16d1d0', 'short', '3(b). Glycine and glutamic acid behave very differently inside a folded protein. Outline why.', '[]'::jsonb, 2) on conflict (id) do update set prompt = excluded.prompt, options = excluded.options, marks = excluded.marks, kind = excluded.kind;
insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('f0489779-e5cf-5557-a839-9effac16d1d0', 'Glycine''s R group is a single hydrogen: tiny and non-polar, so the chain can bend tightly. Glutamic acid''s R group ends in a carboxyl that ionises to –COO⁻: negatively charged and hydrophilic, so it sits on the surface in contact with water and can form ionic bonds.', 'Glycine''s R group is a single hydrogen: tiny and non-polar, so the chain can bend tightly. Glutamic acid''s R group ends in a carboxyl that ionises to –COO⁻: negatively charged and hydrophilic, so it sits on the surface in contact with water and can form ionic bonds.', '[{"text": "Marking point 1", "any": [], "all": ["glycine", "hydrogen"], "marks": 1}, {"text": "Marking point 2", "any": [], "all": ["glutamic", "charge"], "marks": 1}]'::jsonb, 'Glycine''s R group is a single hydrogen: tiny and non-polar, so the chain can bend tightly. Glutamic acid''s R group ends in a carboxyl that ionises to –COO⁻: negatively charged and hydrophilic, so it sits on the surface in contact with water and can form ionic bonds.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
