insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('c5c24f4a-36a9-5835-8493-28b8a0e3def6', 'Dipeptide: two amino acids joined by one peptide bond. Oligopeptide: a short chain, roughly 2 to 20 amino acids. Polypeptide: a long chain of many amino acids, usually more than 20, joined by peptide bonds.', 'Dipeptide: two amino acids joined by one peptide bond. Oligopeptide: a short chain, roughly 2 to 20 amino acids. Polypeptide: a long chain of many amino acids, usually more than 20, joined by peptide bonds.', '[{"text": "Marking point 1", "any": [], "all": ["dipeptide", "two"], "marks": 1}, {"text": "Marking point 2", "any": [], "all": ["oligopeptide", "short"], "marks": 1}, {"text": "Marking point 3", "any": [], "all": ["polypeptide", "long"], "marks": 1}]'::jsonb, 'Dipeptide: two amino acids joined by one peptide bond. Oligopeptide: a short chain, roughly 2 to 20 amino acids. Polypeptide: a long chain of many amino acids, usually more than 20, joined by peptide bonds.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
