insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('5d09bd58-1d14-5005-b3ea-accaccbe481b', 'Essential: the body cannot synthesise it (or not fast enough), so it must be supplied in the diet; nine for adults. Non-essential: the body can synthesise it, usually from another amino acid, so it need not be eaten.', 'Essential: the body cannot synthesise it (or not fast enough), so it must be supplied in the diet; nine for adults. Non-essential: the body can synthesise it, usually from another amino acid, so it need not be eaten.', '[{"text": "Marking point 1", "any": [], "all": ["essential", "cannot"], "marks": 1}, {"text": "Marking point 2", "any": [], "all": ["non essential", "can synthes"], "marks": 1}]'::jsonb, 'Essential: the body cannot synthesise it (or not fast enough), so it must be supplied in the diet; nine for adults. Non-essential: the body can synthesise it, usually from another amino acid, so it need not be eaten.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
