insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('d127325a-8a3f-58f7-9c5e-e1d3607f5af4', 'Plant cells synthesise all twenty amino acids, using nitrate or ammonium from the soil and carbon compounds from photosynthesis; animal cells can make only some, so the rest must come from digesting dietary protein.', 'Plant cells synthesise all twenty amino acids, using nitrate or ammonium from the soil and carbon compounds from photosynthesis; animal cells can make only some, so the rest must come from digesting dietary protein.', '[{"text": "Marking point 1", "any": [], "all": ["plant", "synthes"], "marks": 1}, {"text": "Marking point 2", "any": [], "all": ["animal", "diet"], "marks": 1}]'::jsonb, 'Plant cells synthesise all twenty amino acids, using nitrate or ammonium from the soil and carbon compounds from photosynthesis; animal cells can make only some, so the rest must come from digesting dietary protein.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
