insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('40ed72ac-4acb-5479-bfa5-58c26d550916', 'Protein synthesis needs all nine essential amino acids present together and stops when one runs out; maize gives only 44 % of the lysine requirement, so lysine limits how much protein is made, and the surplus of the others cannot be stored (it is deaminated and excreted as urea).', 'Protein synthesis needs all nine essential amino acids present together and stops when one runs out; maize gives only 44 % of the lysine requirement, so lysine limits how much protein is made, and the surplus of the others cannot be stored (it is deaminated and excreted as urea).', '[{"text": "Marking point 1", "any": ["all nine", "all essential", "runs out", "stops", "limit"], "all": [], "marks": 1}, {"text": "Marking point 2", "any": ["lysine", "cannot be stored", "not stored", "deaminat", "urea", "44"], "all": [], "marks": 1}]'::jsonb, 'Protein synthesis needs all nine essential amino acids present together and stops when one runs out; maize gives only 44 % of the lysine requirement, so lysine limits how much protein is made, and the surplus of the others cannot be stored (it is deaminated and excreted as urea).') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
