insert into public.question_answers (question_id, model_answer, mark_scheme, points, explanation) values ('03b58d53-ec7e-5ba2-a857-4c34f1f404a5', 'No single plant staple supplies all nine essential amino acids in adequate amounts (cereals low in lysine, legumes low in methionine), so complementary plant proteins must be combined, e.g. maize with beans (githeri), rice with lentils.', 'No single plant staple supplies all nine essential amino acids in adequate amounts (cereals low in lysine, legumes low in methionine), so complementary plant proteins must be combined, e.g. maize with beans (githeri), rice with lentils.', '[{"text": "Marking point 1", "any": ["combin", "complementary", "githeri", "maize and beans", "rice and lentils", "together", "soya", "quinoa"], "all": [], "marks": 1}]'::jsonb, 'No single plant staple supplies all nine essential amino acids in adequate amounts (cereals low in lysine, legumes low in methionine), so complementary plant proteins must be combined, e.g. maize with beans (githeri), rice with lentils.') on conflict (question_id) do update set model_answer = excluded.model_answer, mark_scheme = excluded.mark_scheme, points = excluded.points, explanation = excluded.explanation;
